// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount, address actor) public {
        amount = bound(amount, 1, 1e30);
        vm.assume(actor != address(c));

        // actor deposits `amount`, fully backed by credit and balance
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // first withdrawal succeeds and pays out the full credit
        vm.prank(actor);
        bool firstOk;
        try c.withdrawAll() { firstOk = true; } catch { firstOk = false; }

        // Rule: once credit has been consumed, a later withdrawAll by the same
        // actor is a no-op and must NOT revert. The mutant never resets credit,
        // so the second attempt underflows `balance` and reverts.
        vm.prank(actor);
        bool secondOk;
        try c.withdrawAll() { secondOk = true; } catch { secondOk = false; }

        assertTrue(firstOk && secondOk);
    }
}
